[{"order":1,"type":"heading","text":"Node.js Stream Module: Handling Streaming Data"},{"order":2,"type":"paragraph","text":"Node.js streams are a fundamental concept for handling streaming data efficiently. They allow you to process data piece by piece, without loading the entire dataset into memory. This is crucial for handling large files, network communication, and other scenarios where data arrives in chunks."},{"order":3,"type":"subheading","text":"Understanding Streams"},{"order":4,"type":"paragraph","text":"A stream is an abstract interface for working with streaming data in Node.js. There are four fundamental stream types:"},{"order":5,"type":"bullet_point","text":"Readable: Streams from which data can be read (e.g., reading from a file)."},{"order":6,"type":"bullet_point","text":"Writable: Streams to which data can be written (e.g., writing to a file)."},{"order":7,"type":"bullet_point","text":"Duplex: Streams that are both Readable and Writable (e.g., a TCP socket)."},{"order":8,"type":"bullet_point","text":"Transform: Duplex streams that modify or transform the data as it is written and read (e.g., compression or encryption)."},{"order":9,"type":"subheading","text":"Readable Streams"},{"order":10,"type":"paragraph","text":"Readable streams emit events like 'data', 'end', and 'error'. The 'data' event is emitted whenever a chunk of data is available. The 'end' event is emitted when there is no more data to read. The 'error' event is emitted if an error occurs."},{"order":11,"type":"code","text":"// Example: Reading from a file using a Readable stream
const fs = require('fs');

const readableStream = fs.createReadStream('input.txt');

readableStream.on('data', (chunk) => {
  console.log(`Received ${chunk.length} bytes of data`);
  // Process the chunk of data
});

readableStream.on('end', () => {
  console.log('Finished reading the file');
});

readableStream.on('error', (err) => {
  console.error(`An error occurred: ${err}`);
});"},{"order":12,"type":"subheading","text":"Writable Streams"},{"order":13,"type":"paragraph","text":"Writable streams allow you to write data to a destination. They emit events like 'drain', 'finish', and 'error'. The 'drain' event is emitted when the stream's buffer is empty and more data can be written. The 'finish' event is emitted after the stream.end() method has been called, and all data has been flushed to the underlying system. The 'error' event is emitted if an error occurs."},{"order":14,"type":"code","text":"// Example: Writing to a file using a Writable stream
const fs = require('fs');

const writableStream = fs.createWriteStream('output.txt');

writableStream.write('Some data to write to the file.\n');
writableStream.write('Another line of data.\n');

writableStream.end(() => {
  console.log('Finished writing to the file');
});

writableStream.on('error', (err) => {
  console.error(`An error occurred: ${err}`);
});"},{"order":15,"type":"subheading","text":"Duplex Streams"},{"order":16,"type":"paragraph","text":"Duplex streams are both Readable and Writable. A common example is a TCP socket, where you can both send and receive data.  They implement both the Readable and Writable stream interfaces."},{"order":17,"type":"code","text":"// Example: Using a Duplex stream (simplified example using net module)
const net = require('net');

const server = net.createServer((socket) => {
  console.log('Client connected');

  socket.on('data', (data) => {
    console.log(`Received data: ${data.toString()}`);
    socket.write(`Echo: ${data}`); // Echo back the data
  });

  socket.on('end', () => {
    console.log('Client disconnected');
  });

  socket.on('error', (err) => {
    console.error(`Socket error: ${err}`);
  });
});

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":18,"type":"subheading","text":"Transform Streams"},{"order":19,"type":"paragraph","text":"Transform streams are a type of Duplex stream that modifies or transforms the data as it passes through.  They are useful for tasks like compression, encryption, or data formatting. You can create custom transform streams by extending the 'stream.Transform' class."},{"order":20,"type":"code","text":"// Example: Creating a Transform stream to convert data to uppercase
const { Transform } = require('stream');

class UppercaseTransform extends Transform {
  constructor(options) {
    super(options);
  }

  _transform(chunk, encoding, callback) {
    const transformedData = chunk.toString().toUpperCase();
    callback(null, transformedData); // Pass the transformed data
  }
}

// Usage
const uppercaseTransform = new UppercaseTransform();

uppercaseTransform.on('data', (chunk) => {
  console.log(`Transformed data: ${chunk}`);
});

uppercaseTransform.write('hello, world!\n');
uppercaseTransform.end();"},{"order":21,"type":"subheading","text":"Piping Streams"},{"order":22,"type":"paragraph","text":"The 'pipe()' method provides a convenient way to connect Readable and Writable streams, automatically managing the flow of data between them. It handles backpressure, preventing one stream from overwhelming the other."},{"order":23,"type":"code","text":"// Example: Piping a Readable stream to a Writable stream
const fs = require('fs');

const readableStream = fs.createReadStream('input.txt');
const writableStream = fs.createWriteStream('output.txt');

readableStream.pipe(writableStream);

writableStream.on('finish', () => {
  console.log('Finished piping data');
});"},{"order":24,"type":"paragraph","text":"Streams are a powerful tool for handling data efficiently in Node.js. Understanding the different stream types and how to use them is essential for building scalable and performant applications."}]
